var DATA = {"frm": "stopped", "to": "running", "trigger": "start", "guard": "config valid", "action": "bind ports, load state", "invariant": "never half-started", "events": "start|start blocked|status"};
console.log("Transition: " + DATA.frm + " --[" + DATA.trigger + "]--> " + DATA.to);
console.log("Guard: " + DATA.guard + " | Action: " + DATA.action);
console.log("Invariant: " + DATA.invariant);
var state = DATA.frm, log = [];
DATA.events.split("|").forEach(function (ev) {
  ev = ev.trim();
  var guardOk = ev.toLowerCase().indexOf("blocked") < 0; // "blocked" events fail the guard
  if (ev === DATA.trigger && guardOk) {
    log.push(state + " -" + ev + "-> " + DATA.to);
    state = DATA.to;
    console.log("  event '" + ev + "': guard PASS, action ran -> state=" + state);
  } else if (ev === DATA.trigger) {
    console.log("  event '" + ev + "': guard FAIL, stayed in " + state);
  } else {
    console.log("  event '" + ev + "': ignored in " + state);
  }
  // invariant check: state must always be a known state
  if ([DATA.frm, DATA.to].indexOf(state) < 0) console.log("  INVARIANT VIOLATED!");
});
console.log("RESULT: " + log.length + " transition(s) fired; final state=" + state + "; invariant held.");

